learn=[('Define focused specialists', 'Use the agents option with separate description and prompt fields. A reviewer and a test runner have different expertise and tool capabilities.'), ('Delegate through Agent', 'The parent invokes specialists through the real Agent tool. Inspect native tool-use IDs, child tool events and returned reports to distinguish delegation from a parent-only answer.'), ('Give a clear task brief', 'A fresh child does not automatically receive the parent’s history or system prompt. Compare a withheld classroom label with one explicitly supplied in the delegation prompt.'), ('Restrict each child’s tools', 'The code reviewer has Read, Grep and Glob; the test runner can execute one fixed Node test command. The intentionally flawed fixture is read-only throughout the lab.'), ('Inspect concurrency and models', 'Request two specialists in one turn and inspect actual start/stop times. Compare inherited and Haiku reviewer models using observed IDs and SDK-reported estimates, without promising a universal speed or cost result.'), ('Compare three creation paths', 'Run programmatic definitions, a real .claude/agents/file-reviewer.md definition loaded from project settings, and the SDK’s built-in general-purpose agent.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3143\n# Windows only, if needed:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Use Node.js 24+, model API access and available credit. Windows may require Git Bash; the test-runner executes one real Node command through Bash. Model comparison requires Haiku access. No GitHub token or remote service is required.', 'node --version\nnpm --version'), ('Install and configure .env', 'Install pinned dependencies. Preserve an existing .env and enter your API key privately. The model key remains on the server and in the SDK subprocess environment.', 'cd .\\agent-sdk\\lesson43-subagents\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start and navigate', 'Keep the terminal open and use all five navigation buttons. All scenarios finish automatically and display native delegation evidence.', 'npm start\n# http://127.0.0.1:3143'), ('Run specialists and a team', 'Reviewer reads the toy module. Tests runs the actual assertion suite, including its intentional failure. Team requests both specialists in one turn and waits for reports. Inspect start/stop times; concurrency is observed rather than assumed.', 'npm run sample:env -- reviewer\nnpm run sample:env -- tests\nnpm run sample:env -- team'), ('Compare isolation and explicit briefing', 'Isolation withholds the parent-only classroom label from the child task. Briefing explicitly supplies BRIEF-43. Readonly verifies the reviewer’s declared tools and actual child calls while file hashes remain unchanged.', 'npm run sample:env -- isolation\nnpm run sample:env -- briefing\nnpm run sample:env -- readonly'), ('Compare models and creation paths', 'Model repeats the reviewer task with inherited and Haiku child models. Inspect observed IDs and native result estimates; these are not a controlled benchmark. Filesystem loads a real project agent definition; Builtin delegates to general-purpose.', 'npm run sample:env -- model\nnpm run sample:env -- filesystem\nnpm run sample:env -- builtin\nnpm test')]
specs=[('Validate the classroom scenario', 'src/modes.ts', 'export function validateConfig', 'The browser selects a fixed experiment; it cannot inject agent definitions, model IDs, task prompts or arbitrary paths.', 0, 1, 7), ('Define when and how a specialist works', 'src/agents.ts', '"code-reviewer": {', 'description guides specialist selection; prompt defines its role and behavior. These required fields serve different purposes.', 1, 3, 5), ('Choose child tools and model', 'src/agents.ts', 'tools: ["Read", "Grep", "Glob"],', 'Give the reviewer a read-only tool set. The model comparison changes its model override while the task and fixture remain fixed.', 1, 3, 4), ('Attach definitions and enable Agent', 'src/agent.ts', 'agents:', 'Programmatic modes pass the agents option and allow the actual Agent tool. Filesystem and built-in modes omit programmatic definitions.', 1, 2, 8), ('Observe a native delegation', 'src/agent.ts', 'if (!parentId && (b.name === "Agent"', 'Detect top-level Agent tool-use blocks and retain their actual IDs and delegation inputs. A parent answer alone is not proof of delegation.', 1, 2, 5), ('Observe a real specialist start', 'src/agent.ts', 'if (i.hook_event_name === "SubagentStart")', 'Native start hooks identify the actual child and its start time. Independent start/stop events allow inspection of requested concurrency.', 2, 3, 7), ('Constrain reads and test execution', 'src/policy.ts', 'if (name === "Bash")', 'Permit only the exact classroom test command. Read and scan capabilities remain inside the isolated fixture project; edits are rejected.', 3, 4, 8), ('Correlate child tools with the Agent call', 'src/agent.ts', '} else if (parentId) {', 'Child tool-use messages carry parent_tool_use_id. Correlate the nested activity with the originating Agent tool ID.', 3, 0, 4), ('Separate child text from parent output', 'src/agent.ts', 'if (b.type === "text")', 'Forwarded child text is shown in host telemetry; parent assistant text is rendered separately. Host observability is not the parent model’s full context.', 3, 0, 5), ('Recognize the Agent tool return', 'src/agent.ts', 'if (delegations.some', 'Record actual Agent returns. A foreground return may contain the final report; background launches can be receipts followed by native completion notifications.', 3, 1, 5), ('Capture native child completion', 'src/agent.ts', 'if (i.hook_event_name === "SubagentStop")', 'Record the native stop event and its final assistant message when provided. Preserve lifecycle timing instead of inventing progress.', 3, 1, 8), ('Observe filesystem agent definitions', 'src/workspace.ts', 'join(cwd, ".claude", "agents", "file-reviewer.md")', 'Create a real project Markdown agent definition. Project setting sources let the SDK discover it, while programmatic agents are omitted in that mode.', 1, 4, 3), ('Verify the fixture remains unchanged', 'src/agent.ts', 'fixtureUnchanged: before.hash === after.hash', 'Independently hash both fixture and tests after all reports. A successful reviewer result must not imply unobserved edits or fabricated test execution.', 1, 4, 5)]
document('/','A team of <em>focused specialists.</em>','Define specialists, delegate real work and inspect parent/child evidence.','<div class="flow"><div><b>01 · Define</b><p>Role, prompt, tools, model</p></div><span>→</span><div><b>02 · Delegate</b><p>Actual Agent tool calls</p></div><span>→</span><div><b>03 · Observe</b><p>Child loops and reports</p></div></div><section class="panel" id="controls"><h2>Explore SDK subagents</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Subagent experiment</label><select id="mode"><option value="reviewer">Programmatic · read-only code reviewer</option><option value="tests">Programmatic · real test runner</option><option value="team">Two specialists · request concurrent work</option><option value="isolation">Fresh context · parent-only label withheld</option><option value="briefing">Explicit briefing · task label supplied</option><option value="readonly">Tool restrictions · reviewer cannot run shell</option><option value="model">Model choice · inherited versus Haiku</option><option value="filesystem">Filesystem · project agent definition</option><option value="builtin">Built-in · general-purpose subagent</option></select><button id="run" class="primary" disabled>Run subagent experiment →</button><p class="meta">Real parent and child SDK model calls. The toy role-check module deliberately fails one assertion; it is not production authentication. Only fixed reads and the exact classroom test command are permitted. SDK threshold: $0.60 per parent query. Temporary files and transcripts are removed afterward.</p></section><section class="step" id="picker-panel"><h2>Inspect an actual delegation</h2><p id="choice-status" class="note">Choose an Agent tool-use ID to inspect its correlated host-side child telemetry.</p><label for="session-picker">Actual Agent tool-use IDs</label><select id="session-picker"><option>No delegations yet</option></select><button id="resume-session" style="display:none!important" hidden disabled>Resume selected session</button></section><section class="step" id="specialists-panel"><h2>Actual specialist activity</h2><div class="grid" id="specialists"></div><p>Native SubagentStart and SubagentStop events drive these cards. Host telemetry is separate from the parent model’s context.</p></section><div class="workspace"><section class="panel" id="chat-panel"><h2 id="status" aria-live="polite">Ready</h2><div id="conversation"></div></section><section class="panel" id="option-panel"><h2>Host configuration</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Each query and its actual agent definitions, tools and model options appear in the observation selector.</p></section></div><section class="step" id="comparison-panel"><h2>Actual parent responses</h2><div class="grid" id="branch-cards"></div></section><section class="step" id="results-panel"><h2>Actual results, session IDs and processes</h2><div class="table"><table><thead><tr><th>Query</th><th>Stage</th><th>Status</th><th>session_id</th><th>Result text</th></tr></thead><tbody id="result-history"></tbody></table></div><pre class="json-view"><code id="latest-result" class="language-json">{}</code></pre></section><section class="step" id="catalog-panel"><h2>Actual delegation catalog</h2><pre class="json-view"><code id="catalog" class="language-json">[]</code></pre></section><section class="step" id="messages-panel"><h2>Correlated child tools and reports</h2><pre class="json-view"><code id="messages" class="language-json">{}</code></pre><p>These are actual child messages forwarded to the host with parent_tool_use_id, not a claim that all child tool results enter the parent model context.</p></section><section class="step" id="storage-panel"><h2>Definitions, tools, reports and fixture evidence</h2><pre class="json-view"><code id="storage" class="language-json">{}</code></pre><p>Inspect actual definitions, delegation inputs, child tools, reports, lifecycle times and observed model IDs. The fixture hash must remain unchanged.</p></section><section class="step" id="observation-panel"><h2>Inspect actual parent and specialist events</h2><label for="observation-select">Observed arrival sequence</label><select id="observation-select"><option>No observations yet</option></select><pre class="json-view"><code id="selected-observation" class="language-json">{}</code></pre></section><section class="step" id="evidence-panel"><h2>Independent run evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><button id="download">Download actual observations</button></section>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Understand specialist roles, context isolation and scoped tools.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your .env configuration</h2>'+snippet(env,'dotenv')+'<p>Only your model key is required. Keep it local and restart after edits. Existing shell variables take precedence.</p></section><section class="note"><h3>Troubleshooting</h3><p>Use Node 24+, API credit and a supported model. Configure Git Bash on Windows if requested. If the port is occupied, use the printed existing-app URL or change PORT. All experiments finish automatically. Inspect an Agent tool-use ID without sending another model prompt. Consume the entire query stream: asynchronous child completions can produce multiple native parent result frames. Change PORT if 3143 is occupied.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install the SDK, configure your key and run the classroom comparisons.',body)
steps=[];arrows=[];lanes=['Student UI','TypeScript host','Agent tool','Specialists','Classroom files']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 43 · Define → delegate → observe → verify</text>']
for x,label,colour in zip(xs,lanes,['#087fff','#8838ff','#00a977','#8838ff','#ee5425']):svg.append(f'<rect x="{x-150}" y="90" width="300" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" fill="white">{escape(label)}</text><path d="M{x} 170 V1550" stroke="#aec6df" stroke-dasharray="8 7"/>')
for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;path=f'M{x1} {y} h65 v24 h-65' if a==b else f'M{x1} {y} H{x2}';svg.append(f'<text x="{min(x1,x2)+10}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="{path}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'])+'</section>'
document('/architecture.html','Architecture and <em>UML workflow.</em>','Every workflow step includes its corresponding coloured code excerpt.','<p class="note">The diagram groups programmatic definitions, actual Agent tool calls, specialist loops and returned reports. Team mode requests concurrent work; inspect native times to observe actual scheduling. Numbered steps group teaching scenarios rather than one universal sequence.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen source-linked session workflow steps"></div>'+walk)

reference=[('Three actual creation paths', 'Programmatic modes use AgentDefinition objects. Filesystem mode loads .claude/agents/file-reviewer.md from an isolated project. Builtin mode invokes general-purpose. Each scenario verifies native Agent calls and child activity.'), ('Parent context versus host telemetry', 'Fresh children receive their role and task prompt, not the parent system prompt/history automatically. Project instructions can be inherited. forwardSubagentText explicitly exposes nested messages to this app’s host inspector; this does not insert every child tool call into the parent model context.'), ('Asynchronous results', 'Current SDK/CLI versions can launch child tasks asynchronously. Consume the whole query stream, inspect task events and child stop reports, and do not stop at the first parent result frame. Agent returns can be launch receipts rather than final reports.'), ('Measured scheduling', 'Team requests two specialists together. Native start and stop timestamps reveal the actual scheduling. Overlap, total latency and speedups vary with model scheduling and service conditions; this app does not promise that every run is parallel.'), ('Model and cost comparison', 'Model runs the same reviewer task with inherited and Haiku overrides. Display actual observed model IDs and SDK-reported result estimates. Prompt caching, multiple parent result frames and workload variation mean these numbers are not a universal price/performance benchmark; do not blindly sum cumulative frames.'), ('Tool scope and fixture purpose', 'The reviewer has Read/Grep/Glob; the test runner additionally has its exact Bash test command. Global hooks reject unrelated commands, paths, writes and unknown agent types. The toy substring role check is intentionally flawed; it is not production authentication guidance.'), ('Version and lifetime', 'AgentDefinition fields and asynchronous behavior depend on SDK/CLI version. This app pins its SDK, keeps all project settings isolated and removes fixtures, definitions and transcripts after evidence collection. The built-in model may vary; report observed IDs rather than assume them.')]
document('/walkthrough.html','How the app <em>was built.</em>','Every architecture step has source-linked coloured code.',cards(reference)+walk)
readme='# Claude Agent SDK · Lesson 43 · Subagents fundamentals\n\nFive linked student pages, large text, actual SDK experiments and coloured code in all thirteen UML steps.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n' for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson43-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson43-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations use `cd .\\agent-sdk\\lesson43-subagents`. Open http://127.0.0.1:3143 and keep the terminal running. Node.js 24+, API credit and model access are required. Windows may require Git Bash.\n\n## Create your .env file\n\nPreserve an existing file. Enter your own model key, then restart. Existing shell values take precedence.\n\n```dotenv\n'+env+'\n```\n\nNo GitHub token or Managed Agents IDs are required. Secrets, dependencies and teaching media stay outside Git.\n\n## Run the experiments\n\n'
for title,explanation,code in runsteps[3:]:readme+=f'### {title}\n\n{explanation}\n\n```powershell\n{code}\n```\n\n'
readme+='## How the app was built\n\n'
for step in steps:readme+=f'### {step["number"]}. {step["title"]}\n\n{step["explanation"]}\n\nSource: `{step["source"]}`, selected lines {step["firstLine"]}–{step["lastLine"]}. Surrounding code omitted.\n\n```typescript\n{step["code"]}\n```\n\n'
readme+='## Reference topics and limits\n\n'+''.join(f'- {a}: {b}\n' for a,b in reference)+'\n## References\n\n- [Official SDK subagents documentation](https://code.claude.com/docs/en/agent-sdk/subagents)\n- [TypeScript SDK reference](https://code.claude.com/docs/en/agent-sdk/typescript)\n\nRegenerate student pages with `python scripts/build-pages.py`. Run `npm test` for specialist definitions, bounded delegation, scoped tools, actual fixture behavior and startup checks.\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
print('Built five Lesson 43 pages and thirteen source-linked UML steps.')

(PUBLIC/"style.css").write_text((PUBLIC/"style.css").read_text(encoding="utf-8")+'\n#conversation{max-height:540px;overflow:auto}.markdown-body{font-size:22px;line-height:1.6}.markdown-body article,#conversation article{padding:16px;border-bottom:1px solid var(--line)}.json-view{max-height:380px}#result-history td{max-width:380px;overflow-wrap:anywhere}.table{max-height:350px;overflow:auto}#branch-cards{grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr))}#branch-cards .branch-card{padding:20px;overflow-wrap:anywhere}#branch-cards .meta{font-size:20px}#session-picker{font-size:21px}#picker-panel .meta{margin-bottom:0}\n',encoding="utf-8")
